function withProviderSharedFields<T extends {
    readonly authoring: Readonly<Record<string, unknown>> & {
        readonly credentialStyle: Readonly<Record<string, string>>;
    };
    readonly detail: Readonly<Record<string, unknown>>;
    readonly models: Readonly<Record<string, unknown>>;
    readonly status: Readonly<Record<string, string>>;
    readonly errors: Readonly<Record<string, string>>;
}, Locale extends keyof typeof localTranslations>(
    translation: T,
    locale: Locale,
) {
    return {
        ...translation,
        ...providerAvailabilityTranslations[locale],
        links: providerLinkTranslations[locale],
        searchEmptyTitle: providerCompletenessTranslations[locale].searchEmptyTitle,
        searchEmptyDescription: providerCompletenessTranslations[locale].searchEmptyDescription,
        status: { ...translation.status, partial: providerPartialStatusTranslations[locale] },
        errors: {
            ...translation.errors,
            machineCleanupPendingDescription: providerMachineCleanupPendingTranslations[locale],
            connectionChangedTitle: providerConnectionChangedTranslations[locale].title,
            connectionChangedDescription: providerConnectionChangedTranslations[locale].description,
            rpcResponseInvalidTitle: translation.errors.genericTitle,
            rpcResponseInvalidDescription: translation.errors.genericDescription,
            mutationOutcomeUnknownTitle: translation.errors.genericTitle,
            mutationOutcomeUnknownDescription: translation.errors.genericDescription,
            accessChangedTitle: translation.errors.notEnabledOnMachineTitle,
            accessChangedDescription: translation.errors.notEnabledOnMachineDescription,
            incompatibleTitle: providerCompatibilityTranslations[locale].incompatible,
            incompatibleDescription: providerCompatibilityTranslations[locale].incompatibleDescription,
            unverifiedTitle: providerCompatibilityTranslations[locale].experimental,
            unverifiedDescription: providerCompatibilityTranslations[locale].experimentalDescription,
            credentialUnsupportedTitle: providerCompatibilityTranslations[locale].incompatible,
            credentialUnsupportedDescription: providerCompatibilityTranslations[locale].incompatibleDescription,
            connectionInvalidTitle: translation.errors.genericTitle,
            connectionInvalidDescription: translation.errors.genericDescription,
            modelNotFoundTitle: translation.errors.notFoundTitle,
            modelNotFoundDescription: translation.errors.notFoundDescription,
            modelUnloadedTitle: translation.errors.genericTitle,
            modelUnloadedDescription: translation.errors.genericDescription,
            restartRequiredTitle: translation.errors.genericTitle,
            restartRequiredDescription: translation.errors.genericDescription,
            probeExpiredTitle: translation.errors.genericTitle,
            probeExpiredDescription: translation.errors.genericDescription,
            settingsLimitTitle: translation.errors.genericTitle,
            settingsLimitDescription: translation.errors.genericDescription,
            migrationChangedTitle: translation.errors.genericTitle,
            migrationChangedDescription: translation.errors.genericDescription,
            migrationMissingTitle: translation.errors.notFoundTitle,
            migrationMissingDescription: translation.errors.notFoundDescription,
            migrationConflictTitle: translation.errors.genericTitle,
            migrationConflictDescription: translation.errors.genericDescription,
            actions: providerCompletenessTranslations[locale].recoveryActions,
        },
        compatibility: {
            ...providerCompatibilityTranslations[locale],
            reasons: providerCompletenessTranslations[locale].compatibilityReasons,
        },
        migration: {
            ...providerMigrationTranslations[locale],
            ...providerMigrationPreviewTranslations[locale],
            ...providerMigrationConflictTranslations[locale],
            credentialSelectionRequired: providerCredentialSelectionRequiredTranslations[locale],
            credentialFormatSelectionRequired: providerCredentialFormatSelectionRequiredTranslations[locale],
            reservedEnvironmentValidationUnavailable: providerReservedEnvironmentValidationUnavailableTranslations[locale],
        },
        local: {
            ...localTranslations[locale],
            ...providerSharedFieldTranslations[locale].local,
            ...providerManagedDeploymentTranslations[locale],
        },
        detail: {
            ...translation.detail,
            copyName: copyNameTranslations[locale],
            testOnFirstSession: providerFirstSessionValidationTranslations[locale],
        },
        authoring: {
            ...translation.authoring,
            ...providerAdvancedAuthoringTranslations[locale],
            ...providerLocalAuthoringTranslations[locale],
            ...providerAuthoringReviewTranslations[locale],
            unsavedDescription: providerCompletenessTranslations[locale].unsavedDescription,
            publicHeaders: providerNonSecretHeaderTranslations[locale],
            optionalProbePath: providerProbePathsTranslations[locale],
            credentialStyle: {
                ...translation.authoring.credentialStyle,
                customHeaderBearer: providerCustomBearerHeaderTranslations[locale],
            },
            credentialHeaderPlaceholder: 'X-API-Key',
            modelsPathPlaceholder: '/v1/models',
            apiKeyOptionalDescription: providerSharedFieldTranslations[locale].apiKeyOptionalDescription,
        },
        models: {
            ...translation.models,
            ...providerSharedFieldTranslations[locale].models,
            ...providerModelSectionTranslations[locale],
            ...providerModelLoadCancellationTranslations[locale],
            notLoaded: providerModelNotLoadedTranslations[locale],
            connectedServiceSuppressed: providerConnectedServiceSuppressedTranslations[locale],
            hiddenForAllAgents: providerCompletenessTranslations[locale].hiddenForAllAgents,
        },
    } as const;
}

